      expect(controller.submitComment).toHaveBeenCalledTimes(1);
      controller.canSubmit = false;
      await render();
      expect(host.querySelector<HTMLButtonElement>('.message-composer-send-button')!.disabled).toBe(
        true
      );
      await act(async () => {
        root.unmount();
      });
    }
  );
});

