    { ...thinking, privateNative: 'PRIVATE-source' }, child,
  ];
  const body = {
    schemaVersion: 1 as const, binding: target, sequence: 2, writerIncarnation: 'host-1',
    stateDigest: runtimeDigest({}),
    events: facts.map((data, index) => ({
