      const parent = censusReads > 1 && mode === 'reparent' ? 4999 : 4101;
      const argv = censusReads > 1 && mode === 'argv' ? originalCommand + ' --other' : originalCommand;
      return host + `4200 ${parent} 4200 Sun Nov 15 ${birth} 2026 ${argv}\n`;
